                socket_integer(sender.as_raw_fd(), libc::SO_SNDBUF)? > 8192 ||
                unsafe { libc::shutdown(sender.as_raw_fd(), libc::SHUT_RD) } < 0 ||
                unsafe { libc::shutdown(recipient.as_raw_fd(), libc::SHUT_WR) } < 0 {
